def is_valid_sudoku(board):
    def has_duplicates(group):
        digits = [c for c in group if c != '.']
        return len(digits) != len(set(digits))

    for i in range(9):
        if has_duplicates(board[i]):                                       # re-scan this entire row from scratch
            return False
    for j in range(9):
        column = [board[i][j] for i in range(9)]                           # re-scan this entire column from scratch
        if has_duplicates(column):
            return False
    for box_row in range(3):
        for box_col in range(3):
            box = [board[box_row * 3 + r][box_col * 3 + c] for r in range(3) for c in range(3)]   # re-scan this entire 3x3 box from scratch
            if has_duplicates(box):
                return False
    return True


if __name__ == "__main__":
    board = [
        list('53..7....'),
        list('6..195...'),
        list('.98....6.'),
        list('8...6...3'),
        list('4..8.3..1'),
        list('7...2...6'),
        list('.6....28.'),
        list('...419..5'),
        list('....8..79'),
    ]
    print(is_valid_sudoku(board))

