import java.util.*;

public class Main {
    boolean isValidSudoku(char[][] board) {
        for (int i = 0; i < 9; i++) {
            if (hasDuplicates(board[i])) return false;                            // re-scan this entire row from scratch
        }
        for (int j = 0; j < 9; j++) {
            char[] column = new char[9];
            for (int i = 0; i < 9; i++) column[i] = board[i][j];                    // re-scan this entire column from scratch
            if (hasDuplicates(column)) return false;
        }
        for (int boxRow = 0; boxRow < 3; boxRow++) {
            for (int boxCol = 0; boxCol < 3; boxCol++) {
                char[] box = new char[9];
                int idx = 0;
                for (int r = 0; r < 3; r++)
                    for (int c = 0; c < 3; c++)
                        box[idx++] = board[boxRow * 3 + r][boxCol * 3 + c];           // re-scan this entire 3x3 box from scratch
                if (hasDuplicates(box)) return false;
            }
        }
        return true;
    }

    boolean hasDuplicates(char[] group) {
        Set<Character> seen = new HashSet<>();
        for (char c : group) {
            if (c == '.') continue;
            if (!seen.add(c)) return true;
        }
        return false;
    }

    public static void main(String[] args) {
        Main solution = new Main();
        char[][] board = {
            {'5','3','.','.','7','.','.','.','.'},
            {'6','.','.','1','9','5','.','.','.'},
            {'.','9','8','.','.','.','.','6','.'},
