#include <bits/stdc++.h>
using namespace std;

bool hasDuplicates(vector<char>& group) {
    unordered_set<char> seen;
    for (char c : group) {
        if (c == '.') continue;
        if (!seen.insert(c).second) return true;
    }
    return false;
}

bool isValidSudoku(vector<vector<char>>& board) {
    for (int i = 0; i < 9; i++) {
        if (hasDuplicates(board[i])) return false;                              // re-scan this entire row from scratch
    }
    for (int j = 0; j < 9; j++) {
        vector<char> column(9);
        for (int i = 0; i < 9; i++) column[i] = board[i][j];                       // re-scan this entire column from scratch
        if (hasDuplicates(column)) return false;
    }
    for (int boxRow = 0; boxRow < 3; boxRow++) {
        for (int boxCol = 0; boxCol < 3; boxCol++) {
            vector<char> box;
            for (int r = 0; r < 3; r++)
                for (int c = 0; c < 3; c++)
                    box.push_back(board[boxRow * 3 + r][boxCol * 3 + c]);           // re-scan this entire 3x3 box from scratch
            if (hasDuplicates(box)) return false;
        }
    }
    return true;
}

int main() {
    vector<vector<char>> board = {
        {'5','3','.','.','7','.','.','.','.'},
