import java.util.*;

public class Main {
    boolean isValidSudoku(char[][] board) {
        Set<Character>[] rows = new HashSet[9];
        Set<Character>[] cols = new HashSet[9];
        Set<Character>[] boxes = new HashSet[9];                                   // one set per 3x3 box, indexed 0-8 in row-major box order
        for (int k = 0; k < 9; k++) { rows[k] = new HashSet<>(); cols[k] = new HashSet<>(); boxes[k] = new HashSet<>(); }
        for (int i = 0; i < 9; i++) {
            for (int j = 0; j < 9; j++) {
                char c = board[i][j];
                if (c == '.') continue;
                int boxIdx = (i / 3) * 3 + (j / 3);                                  // maps any (i,j) to its containing box's index, 0-8
                if (rows[i].contains(c) || cols[j].contains(c) || boxes[boxIdx].contains(c)) {
                    return false;                                                      // this digit already appeared in its row, column, or box
                }
                rows[i].add(c);
                cols[j].add(c);
                boxes[boxIdx].add(c);
            }
        }
        return true;
    }

    public static void main(String[] args) {
        Main solution = new Main();
